const cfg = $('Carica prompt e contratto').first().json;
const task = `${cfg.contratto_comune}

${cfg.prompt}

Titolo incarico: ${cfg.titolo}

Cerca una fonte consultata con link, preferendo la fonte primaria. Valuta se la fonte conferma tutti i fatti essenziali: usa STATUS: VERIFICATA solo quando li conferma; usa STATUS: NON VERIFICATA se il dato manca, è in conflitto con la fonte o non puoi confermarlo. Non scartare una notizia solo perché non è verificata: mantieni il fatto con formulazione prudente e spiega in FACT che cosa resta incerto o contraddetto. Non aggiungere calcoli obbligatori. Ogni notizia deve avere il link della fonte consultata.

Per ogni notizia produci una sola riga nel formato esatto: NEWS: titolo | FACT: fatto | STATUS: VERIFICATA oppure NON VERIFICATA | URL: https://... | WHY: perché conta. Massimo tre righe. Se non ci sono novità, scrivi esattamente: NESSUN AGGIORNAMENTO — nessuna azione richiesta. Non aggiungere preamboli o blocchi di codice.`;
if (task.length > 32000) throw new Error('Briefing prompt exceeds the 32000-character input cap');
return [{json:{model:'ai-standard',input:task}}];

const r = $json;
const blocks = Array.isArray(r.output) ? r.output.flatMap(o => Array.isArray(o.content) ? o.content : []) : [];
const text = blocks.filter(c => typeof c.text === "string").map(c => c.text).join("\n").trim() || (typeof r.output_text === "string" ? r.output_text.trim() : "");
if (!text) throw new Error("LiteLLM did not return briefing text");
const inlineCitations = blocks.flatMap(c => Array.isArray(c.annotations) ? c.annotations : []).filter(a => a.type === "url_citation" && a.url).map(a => a.url);
const searchedSources = Array.isArray(r.output) ? r.output.filter(o => o.type === "web_search_call").flatMap(o => Array.isArray(o.action?.sources) ? o.action.sources : []).map(s => s.url).filter(url => typeof url === "string" && url) : [];
const citations = [...new Set([...inlineCitations, ...searchedSources])];
function canonicalUrl(value) {
  try {
    const url = new URL(value);
    url.hash = "";
    for (const key of [...url.searchParams.keys()]) if (/^(utm_|ref$|source$)/i.test(key)) url.searchParams.delete(key);
    url.pathname = url.pathname.replace(/\/$/, "");
    url.hostname = url.hostname.toLowerCase();
    const parameters = [...url.searchParams.entries()].sort(([a], [b]) => a.localeCompare(b));
    url.search = "";
    for (const [key, item] of parameters) url.searchParams.append(key, item);
    return url.toString();
  } catch {
    return value;
  }
}
function tokens(value) {
  return value.normalize("NFKD").replace(/[\u0300-\u036f]/g, "").toLowerCase().replace(/[^a-z0-9 ]/g, " ").split(/\s+/).filter(t => t.length > 2 && !["the","and","for","with","from","that","this","della","delle","degli","dell","che","per","una","uno","nel","nella","alla","alle","con","come","dopo","sul","sulla","tra","fra"].includes(t));
}
const candidatePattern = /^\s*(?:[-*]\s*)?NEWS:\s*(.+?)\s*\|\s*FACT:\s*(.+?)\s*\|\s*STATUS:\s*(VERIFICATA|NON VERIFICATA)\s*\|\s*URL:\s*(https?:\/\/\S+?)\s*\|\s*WHY:\s*(.+?)\s*$/gim;
const postedPattern = /^• \*(.+?)\* — (.+?)\n  (?:_Stato: (?:VERIFICATA|NON VERIFICATA)_\n  )?<([^>|]+)\|Fonte>\n  _Perché conta: (.+?)_$/gm;
function parseCandidateRecords(value) {
  return [...value.matchAll(candidatePattern)].map(m => ({title:m[1].trim(),fact:m[2].trim(),status:m[3].toUpperCase(),url:m[4].replace(/[),.;]+$/, ""),why:m[5].trim()}));
}
function parsePublishedRecords(value) {
  return [...value.matchAll(postedPattern)].map(m => ({title:m[1].trim(),fact:m[2].trim(),url:m[3].trim(),why:m[4].trim()}));
}
const linesInText = text.split(/\r?\n/).map(line => line.trim()).filter(Boolean);
const explicitNoUpdates = /^NESSUN AGGIORNAMENTO — nessuna azione richiesta$/i.test(text);
const candidates = parseCandidateRecords(text);
if (explicitNoUpdates) {
  if (linesInText.length !== 1) throw new Error("No-update response contains extra claims");
} else if (linesInText.some(line => /^NESSUN AGGIORNAMENTO\b/i.test(line))) {
  throw new Error("No-update response contains extra claims");
} else if (candidates.length === 0 || candidates.length > 3 || candidates.length !== linesInText.length) {
  throw new Error("Expected one to three complete NEWS/FACT/URL/WHY lines and no other text");
}
function isHttpsLink(value) {
  try {
    const url = new URL(value);
    return url.protocol === "https:" && Boolean(url.hostname) && !url.username && !url.password;
  } catch { return false; }
}
const verifiedUrls = new Set(citations.map(canonicalUrl));
const inlineCitationUrls = new Set(inlineCitations.map(canonicalUrl));
for (const item of candidates) {
  if (!isHttpsLink(item.url)) throw new Error("Briefing source must be an HTTPS link");
  if (!verifiedUrls.has(canonicalUrl(item.url))) throw new Error("Briefing item URL is missing a web_search URL citation");
  if (!inlineCitationUrls.has(canonicalUrl(item.url))) throw new Error("Briefing item URL is not cited inline in the generated answer");
}
const marker = "_Briefing tech quotidiano · ref:daily-tech-briefing_";
const priorMessages = $("Leggi storico del canale").all().map(i => i.json).filter(m => m.user === "U0BP05KJACA" && typeof m.text === "string" && m.text.includes(marker));
const previous = priorMessages.flatMap(m => parsePublishedRecords(m.text));
const seenUrls = new Set(previous.map(item => canonicalUrl(item.url)));
const seenTitles = previous.map(item => new Set(tokens(item.title + " " + item.fact)));
const fresh = candidates.filter(item => {
  const url = canonicalUrl(item.url);
  const words = new Set(tokens(item.title + " " + item.fact));
  const duplicate = seenUrls.has(url) || seenTitles.some(old => {
    const union = new Set([...old, ...words]);
    const overlap = [...words].filter(word => old.has(word)).length;
    return union.size > 0 && overlap / union.size >= 0.6;
  });
  if (duplicate) return false;
  seenUrls.add(url);
  seenTitles.push(words);
  return true;
});
let lines;
if (explicitNoUpdates || fresh.length === 0) {
  lines = ["NESSUN AGGIORNAMENTO — nessuna azione richiesta"];
} else {
  lines = fresh.map(item => "• *" + item.title + "* — " + item.fact + "\n  _Stato: " + item.status + "_\n  <" + item.url + "|Fonte>\n  _Perché conta: " + item.why + "_");
}
const report = [...lines, marker].join("\n\n");
return [{json:{report,priorBriefingCount:previous.length,deduplicatedCount:candidates.length-fresh.length}}];
